/* @lc app=leetcode id=1948 lang=kotlin */
class Node(val name: String, val children: java.util.TreeMap<String, Node> = java.util.TreeMap(), var serial: String = "") class Solution { fun deleteDuplicateFolder(paths: List<List<String>>): List<List<String>> = Node("").apply { paths.forEach { p -> p.fold(this) { curr, f -> curr.children.getOrPut(f) { Node(f) } } } }.let { root -> HashMap<String, Int>().let { count -> Array<(Node) -> String>(1) { { _ -> "" } }.apply { this[0] = { node -> if (node.children.isEmpty()) "" else node.children.entries.joinToString("") { (name, child) -> "$name(${this[0](child)})" }.also { s -> node.serial = s }.also { s -> count[s] = (count[s] ?: 0) + 1 } } }[0](root).let { mutableListOf<List<String>>().also { res -> Array<(Node, MutableList<String>) -> Unit>(1) { { _, _ -> } }.let { dfs2 -> dfs2.apply { this[0] = { node, path -> if (!(node.serial.isNotEmpty() && (count[node.serial] ?: 0) > 1)) listOf(if (node.name.isNotEmpty()) path.add(node.name).also { res.add(ArrayList(path)) } else Unit, node.children.values.forEach { child -> dfs2[0](child, path) }, if (node.name.isNotEmpty()) path.removeAt(path.lastIndex) else Unit) } }[0](root, mutableListOf()) } } } } }